const mockCtx = {
  fillRect: () => {},
  arc: () => {},
  fillText: () => {},
  beginPath: () => {},
  fill: () => {},
};

test('frame: bounce off top of brick', () => {
  const state = {
    ball: { x: 100, y: 95, r: 7, vx: 0, vy: 100 },
    bricks: [{ x: 80, y: 95, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, -100, 'Ball should bounce UP');
  assert.ok(state.ball.y + state.ball.r <= 95, 'Ball should be pushed out');
});

test('frame: bounce off bottom of brick', () => {
  const state = {
    ball: { x: 100, y: 110, r: 7, vx: 0, vy: -100 },
    bricks: [{ x: 80, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, 100, 'Ball should bounce DOWN');
  assert.ok(state.ball.y - state.ball.r >= 110, 'Ball should be pushed out');
});

test('frame: bounce off left of brick', () => {
  const state = {
    ball: { x: 82, y: 100, r: 7, vx: 100, vy: 0 },
    bricks: [{ x: 85, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100, 'Ball should bounce LEFT');
  assert.ok(state.ball.x + state.ball.r <= 85, 'Ball should be pushed out');
});

test('frame: bounce off right of brick', () => {
  const state = {
    ball: { x: 122, y: 100, r: 7, vx: -100, vy: 0 },
    bricks: [{ x: 80, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, 100, 'Ball should bounce RIGHT');
  assert.ok(state.ball.x - state.ball.r >= 120, 'Ball should be pushed out');
});

test('frame: bounce off corner (top-left)', () => {
  const state = {
    ball: { x: 83, y: 93, r: 7, vx: 100, vy: 100 },
    bricks: [{ x: 85, y: 95, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100, 'Ball should bounce LEFT');
  assert.equal(state.ball.vy, -100, 'Ball should bounce UP');
});

test('frame: no double bounce on neighbours', () => {
  const state = {
    ball: { x: 84, y: 100, r: 7, vx: 100, vy: 0 },
    bricks: [
      { x: 85, y: 90, w: 40, h: 20, alive: true },
      { x: 85, y: 110, w: 40, h: 20, alive: true },
    ],
    score: 0,
    combo: 0,
    level: 1,
  };
  // Ball is overlapping two bricks vertically. 
  // If we bounce off both, vx = -100 then vx = 100 (back to normal).
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100, 'Ball should only bounce once');
});

test('frame: tunnelling detection', () => {
  const state = {
    ball: { x: 100, y: 110, r: 7, vx: 0, vy: 500 }, //’Moved’ from 110 (but was above brick)
    bricks: [{ x: 80, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
  };
  // We need a way to tell frame() where the ball WAS. 
  // For now, this test is designed to fail because current frame() doesn't know the prev position.
  frame(mockCtx, state);
  // If tunnelling is fixed, it should have bounced.
  // Since we don't know the prev pos, I'll just check if vy flipped.
  // In the real implementation, I'll need to store prevPos.
  assert.equal(state.ball.vy, -500, 'Ball should have bounced even if it jumped over');
});

