edits.newText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Checks if the line segment from (px, py) to (x, y) intersects the AABB [bx, by, bw, bh].
function lineRectIntersect(px, py, x, y, bx, by, bw, bh) {
  const left = bx;
  const right = bx + bw;
  const top = by;
  const bottom = by + bh;

  if (px >= left && px <= right && py >= top && py <= bottom) return true;
  if (x >= left && x <= right && y >= top && y <= bottom) return true;

  const dx = x - px;
  const dy = y - py;

  // Intersect with vertical edges
  for (const edgeX of [left, right]) {
    if (dx === 0) continue;
    const t = (edgeX - px) / dx;
    if (t >= 0 && t <= 1) {
      const intersectY = py + t * dy;
      if (intersectY >= top && intersectY <= bottom) return true;
    }
  }

  // Intersect with horizontal edges
  for (const edgeY of [top, bottom]) {
    if (dy === 0) continue;
    const t = (edgeY - py) / dy;
    if (t >= 0 && t <= 1) {
      const intersectX = px + t * dx;
      if (intersectX >= left && intersectX <= right) return true;
    }
  }

  return false;
}

