edits.newText:
// Bricks: collision + bounce + score + drawing, all in one place.
let bounced = false;
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  let hit = collides(state.ball, brick);
  if (!hit && !bounced) {
    // Tunnelling check: sweep between positions with an expanded brick box.
    const { ball } = state;
    if (lineRectIntersect(ball.prevX, ball.prevY, ball.x, ball.y, brick.x - ball.r, brick.y - ball.r, brick.w + 2 * ball.r, brick.h + 2 * ball.r)) {
      hit = true;
    }
  }

  if (hit && !bounced) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const { ball } = state;
    const penL = ball.x + ball.r - brick.x;
    const penR = brick.x + brick.w - (ball.x - ball.r);
    const penT = ball.y + ball.r - brick.y;
    const penB = brick.y + brick.h - (ball.y - ball.r);

    const minPen = Math.min(penL, penR, penT, penB);

    if (minPen === penL) {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
    } else if (minPen === penR) {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
    } else if (minPen === penT) {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
    } else if (minPen === penB) {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
    }
    bounced = true;
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

