test('frame: bounce off top of brick', () => {
  const state = {
    ball: { x: 100, y: 95, r: 7, vx: 0, vy: 100, prevX: 100, prevY: 90 },
    bricks: [{ x: 80, y: 95, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
    paddle: { x: 0, y: 0, w: 0, h: 0 },
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, -100, 'Ball should bounce UP');
  assert.ok(state.ball.y + state.ball.r <= 95, 'Ball should be pushed out');
});

test('frame: bounce off bottom of brick', () => {
  const state = {
    ball: { x: 100, y: 110, r: 7, vx: 0, vy: -100, prevX: 100, prevY: 115 },
    bricks: [{ x: 80, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
    paddle: { x: 0, y: 0, w: 0, h: 0 },
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vy, 100, 'Ball should bounce DOWN');
  assert.ok(state.ball.y - state.ball.r >= 110, 'Ball should be pushed out');
});

test('frame: bounce off left of brick', () => {
  const state = {
    ball: { x: 82, y: 100, r: 7, vx: 100, vy: 0, prevX: 75, prevY: 100 },
    bricks: [{ x: 85, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
    paddle: { x: 0, y: 0, w: 0, h: 0 },
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100, 'Ball should bounce LEFT');
  assert.ok(state.ball.x + state.ball.r <= 85, 'Ball should be pushed out');
});

test('frame: bounce off right of brick', () => {
  const state = {
    ball: { x: 122, y: 100, r: 7, vx: -100, vy: 0, prevX: 130, prevY: 100 },
    bricks: [{ x: 80, y: 90, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
    paddle: { x: 0, y: 0, w: 0, h: 0 },
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, 100, 'Ball should bounce RIGHT');
  assert.ok(state.ball.x - state.ball.r >= 120, 'Ball should be pushed out');
});

test('frame: bounce off corner (top-left)', () => {
  const state = {
    ball: { x: 83, y: 93, r: 7, vx: 100, vy: 100, prevX: 75, prevY: 85 },
    bricks: [{ x: 85, y: 95, w: 40, h: 20, alive: true }],
    score: 0,
    combo: 0,
    level: 1,
    paddle: { x: 0, y: 0, w: 0, h: 0 },
  };
  frame(mockCtx, state);
  assert.equal(state.ball.vx, -100, 'Ball should bounce LEFT');
  assert.equal(state.ball.vy, -100, 'Ball should bounce UP');
});

test('frame: no double bounce on neighbours', () => {
  const state = {
    ball: { x: 84, y: 100, r: 7, vx: 100, vy: 0, prevX: 75, prevY: 100 },
    bricks: [
      { x: 85, y: 90, w: 40, h: 20, alive: true },
